import{z as l,x as o,o as n,c as s,q as A,j as B,D as e,d as p,s as t,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"完全竞争的短期与长期","description":"","frontmatter":{"title":"完全竞争的短期与长期","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/perfect-competition.md","filePath":"econ/perfect-competition.md","lastUpdated":1791063341000}'),m={name:"econ/perfect-competition.md"};function C(d,E,D,F,h,f){const r=o("Mermaid");return n(),s("div",null,[E[2]||(E[2]=A('<h1 id="完全竞争的短期与长期" tabindex="-1">完全竞争的短期与长期 <a class="header-anchor" href="#完全竞争的短期与长期" aria-label="Permalink to &quot;完全竞争的短期与长期&quot;">​</a></h1><div class="epigraph"><p>自由进入把长期价格钉在平均成本的最低点；短期里工厂数目给定，价格由需求与既有供给相交决定。</p><footer>—— 据 Marshall, Principles of Economics；Viner, Cost Curves and Supply Curves, 1931 整理</footer></div><p><a href="/econ/returns-vs-economies">上一课</a>（规模报酬对规模经济）。给了单家厂商的停产规则与长短期成本包络。本课不重讲 AVC 与沉没的定义。缺口是：价格仍是参数。市场结构课序从这里打开——把许多价格接受者叠成行业供给，再让需求来定 \\(p\\)，并问进入之后 \\(p\\) 停在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/profit-supply">利润供给</a>的 \\(q(p,w)\\) 是一家的反应。短期厂商数目 \\(n\\) 固定（进入成本已沉没或来不及建厂），行业供给 \\(Q_{\\mathrm{SR}}(p)=n q_{\\mathrm{SR}}(p)\\)（可加异质厂商）。需求 \\(D(p)\\) 与之相交得短期均衡价格。缺口不是再写 \\(p=\\mathrm{MC}\\)，而是：<strong>谁保证这个 \\(p\\) 让在位者刚好不亏、潜在进入者刚好不想进？</strong> 短期不保证。会计利润可以正可以负。</p><p>长期：进入、退出把 \\(n\\) 变成内生。若厂商相同、要素价格不随行业扩张而涨，自由进入把 \\(\\pi\\) 赶到零，\\(p=\\min\\mathrm{AC}\\)，每家产在有效规模。行业长期供给在该价格上无限弹性。要素价格随行业上升时，长期供给向右上倾斜——那是外部不经济，不是单家 DRS 的简单加总。</p><h3 id="零利润是进入条件-不是会计恒等式" tabindex="-1">零利润是进入条件，不是会计恒等式 <a class="header-anchor" href="#零利润是进入条件-不是会计恒等式" aria-label="Permalink to &quot;零利润是进入条件，不是会计恒等式&quot;">​</a></h3><p>CRS 无沉没时，上一课已说 \\(\\pi\\) 在零与无穷之间刀刃。有 U 形 AC 时，零利润是 \\(p=\\min\\mathrm{AC}\\) 的几何，经济利润为零，要素按机会成本付酬。不要读成「厂商没钱可赚所以不生产」：生产在有效规模上发生，只是没有超额。沉没的进入成本摊进 AC，正是为了让「零利润」含正常回报。</p><p><span class="marginnote">术语翻译：经济利润为零不等于白干。若你投 100 万开厂，这笔钱本可买国债每年稳拿 3 万利息——那 3 万就是机会成本，被算进成本里。收入恰好覆盖全部成本时，账面上你仍「赚」了 3 万（正常回报），但没有任何人能靠复制一间同样的厂再多赚一分：吸引新进入者的「超额」部分已经归零。</span></p><p><span class="marginnote">价格接受加自由进入，不自动给出福利最优——那是一般均衡课的第一福利定理，需要完整的商品空间与没有外部性。本课只钉局部市场的价格形成。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>短期：给定 \\(n\\) 与各家 \\(z_f\\)，把停产点以上的短期 MC 水平加总，与 \\(D(p)\\) 联立。参数移动：需求冲击先改 \\(p\\)，再沿短期供给调 \\(q\\)；在位者的准租金可以涨。长期：允许 \\(n\\) 变，新均衡在 \\(p=\\min\\mathrm{AC}\\) 与 \\(D(p)=n q^*\\)，其中 \\(q^*\\) 是有效规模。比较静态要声明走的是哪一条曲线，否则「供给定理」会把短期弹性当成长期。</p><p>相同厂商是教具。成本异质时，长期留下的是 AC 足够低的那些，边际上那家零利润， inframarginal 有租金。本课不把租金写成垄断——来源是稀缺的低成本投入，不是向下的需求曲线。</p>',13)),(n(),B(i,null,{default:e(()=>[t(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIRM%5B%22%E5%8D%95%E5%AE%B6%EF%BC%9A%E7%9F%AD%E9%95%BF%E6%9C%9F%20MC%22%5D%20--%3E%20SUM%5B%22n%20%E5%AE%B6%E5%8A%A0%E6%80%BB%EF%BC%9A%E8%A1%8C%E4%B8%9A%E4%BE%9B%E7%BB%99%22%5D%0A%20%20SUM%20--%3E%20SR%5B%22%E7%9F%AD%E6%9C%9F%EF%BC%9An%20%E5%9B%BA%E5%AE%9A%EF%BC%8CD%20%E4%BA%A4%20S_SR%22%5D%0A%20%20SR%20--%3E%20PI%5B%22%E5%88%A9%E6%B6%A6%E5%8F%AF%E6%AD%A3%E5%8F%AF%E8%B4%9F%22%5D%0A%20%20PI%20--%3E%20ENT%5B%22%E8%BF%9B%E5%85%A5%E9%80%80%E5%87%BA%EF%BC%9An%20%E5%86%85%E7%94%9F%22%5D%0A%20%20ENT%20--%3E%20LR%5B%22%E9%95%BF%E6%9C%9F%EF%BC%9Ap%20%3D%20min%20AC%22%5D%0A%20%20LR%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%8B%A5%E4%B8%8D%E8%83%BD%E8%BF%9B%E5%85%A5%E4%BC%9A%E6%80%8E%E6%A0%B7%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[p(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"需求来自本栏消费者课的马歇尔加总。这里不把加总问题（Gorman、市场 WARP 失败）展开；完全竞争课假定一条向下的 \\(D(p)\\)。要素价格若随行业扩张上扬，长期供给倾斜，那是外部不经济，不要误写成单家 DRS 的加总。",-1)),E[4]||(E[4]=a("p",null,"本课产品同质、信息完全、无策略互动。下一课撤掉「许多家加自由进入」，让单独一家面对整条需求。",-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[p("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"短期 \\(p\\) 变动大、数量调整受既定 \\(z_f\\) 限制，所以供给较陡。长期可以建厂、进入，弹性变大。Marshall 的时期分析就是这套时间分层，不是另一套偏好。进入把超额利润吃掉的机制是：正利润吸引模仿，\\(n\\) 升、\\(p\\) 降，直到 \\(\\pi=0\\)；亏损则反方向。没有进入壁垒时，壁垒不是本课的对象——垄断课才把壁垒当结构。短期准租金（\\(p\\) 高于 AVC、低于 AC）补偿的是已经沉没的 \\(z_f\\)，不是垄断势力：勒纳指数下一课才出场，本课 \\(P=\\mathrm{MC}\\) 在停产点以上始终成立。",-1)),E[7]||(E[7]=a("p",null,"行业长期供给水平的机制是：复制有效规模的工厂不抬要素价格。若土地、矿藏随需求一起涨，\\(w\\) 变成 \\(Q\\) 的函数，单家 AC 上移，行业曲线倾斜。那是外部成本，不要写成单家 IRS/DRS 的误加总。",-1)),E[8]||(E[8]=a("p",null,"进入与退出这条反馈环单独画出来，回答的是「利润最终停在哪」：",-1)),(n(),B(i,null,{default:e(()=>[t(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%9C%A8%E4%BD%8D%E8%80%85%E5%88%A9%E6%B6%A6%E4%B8%BA%E6%AD%A3%22%5D%20--%3E%20B%5B%22%E6%96%B0%E5%8E%82%E5%95%86%E8%BF%9B%E5%85%A5%EF%BC%9An%20%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20B%20--%3E%20C%5B%22%E8%A1%8C%E4%B8%9A%E4%BE%9B%E7%BB%99%E6%9B%B2%E7%BA%BF%E5%8F%B3%E7%A7%BB%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%BB%B7%E6%A0%BC%20p%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20D%20--%3E%20E%7B%22p%20%E4%B8%8E%20min%20AC%20%E7%9B%B8%E6%AF%94%E5%A6%82%E4%BD%95%22%7D%0A%20%20E%20--%20%22%E4%BB%8D%E9%AB%98%E4%BA%8E%20min%20AC%22%20--%3E%20A%0A%20%20E%20--%20%22%E7%AD%89%E4%BA%8E%20min%20AC%22%20--%3E%20F%5B%22%E8%BF%9B%E5%85%A5%E5%81%9C%E6%AD%A2%EF%BC%9A%E9%95%BF%E6%9C%9F%E5%9D%87%E8%A1%A1%22%5D%0A%20%20G%5B%22%E5%9C%A8%E4%BD%8D%E8%80%85%E4%BA%8F%E6%8D%9F%22%5D%20--%3E%20H%5B%22%E5%8E%82%E5%95%86%E9%80%80%E5%87%BA%EF%BC%9An%20%E5%87%8F%E5%B0%91%22%5D%0A%20%20H%20--%3E%20I%5B%22%E4%BE%9B%E7%BB%99%E5%B7%A6%E7%A7%BB%EF%BC%9Ap%20%E5%9B%9E%E5%8D%87%22%5D%20--%3E%20F%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[p(" Loading... ",-1)])]),_:1})),E[9]||(E[9]=A('<p><span class="marginnote">数字实例：设一件产品分摊的固定投入（机器租金）3 元、可变成本（料与人工）6 元、售价 8 元。每件亏 1 元，但仍有 2 元毛利去补那 3 元固定投入——开工比立刻停产少亏。只有售价跌破 6 元的可变成本时，才该马上停机：这就是停产点「售价高于 AVC 就继续干」的含义。</span></p><p>需求的来源是消费课已经写过的马歇尔需求，本课把它当成行业 \\(D(p)\\)，不再对个人加总一遍。要素价格若被本行业抬动，一般均衡会把 \\(w\\) 内生化；局部均衡把 \\(w\\) 当参数，这是本课的工作边界。</p><p><span class="marginnote">量化栏的连续竞价形成的是订单簿价格，不是这里的 \\(D\\) 交 \\(S\\)。本课 \\(p\\) 是参数均衡，没有报价策略。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>产品差异、策略数量、产能约束，都会让「加总 MC」不再是行业供给。那些是本课序后段。也不处理匹配摩擦与数量配给：出清靠价格，不靠排队。税收归宿后课会用本课的短长期弹性，但税本身不在这里引入。</p><p>IRS 与巨大沉没使自由进入的零利润均衡可以不存在，只留下一家——下一课垄断把这件事当成结构。量化栏的连续竞价不是这里的 \\(D\\) 交 \\(S\\)：本课 \\(p\\) 是参数均衡，没有订单队列。</p><p>后课默认：完全竞争短期 \\(n\\) 固定、长期自由进入且经济利润为零；对照垄断时，比较的就是这一基准。</p><p><span class="marginnote">常见误区：短期供给陡、长期供给平，不是说同一条曲线后来「变弯了」，而是陡峭本身来自「工厂数目和产能来不及变」这条约束。做比较静态时先自问一句：这次冲击之后，允许新厂进来吗？答案不同，价格与数量的答案就完全不同。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>短期行业供给是既定 \\(n\\) 下 MC 的加总；价格由需求相交决定。</li><li>长期进入把 \\(p\\) 钉在 \\(\\min\\mathrm{AC}\\)；零利润是进入条件。</li><li>短、长期弹性不同，比较静态必须声明时期。</li><li>下一课撤掉进入与价格接受，面对向下的市场需求。</li><li>出处：Marshall, <em>Principles of Economics</em>；Viner, 1931；Mas-Colell, Whinston and Green 第 10 章。</li></ul>',10))])}const S=l(m,[["render",C]]);export{c as __pageData,S as default};
